<script lang="ts">
  import LayerItem from './LayerItem.svelte';
  import { getEditorContext } from './context.svelte.js';
  import {
    IconChevronDown,
    IconChevronRight,
    IconColumns,
    IconDatabase,
    IconDocument,
    IconEyeOff,
    IconLayers,
    IconLock,
    IconMore,
    IconPanel,
  } from './icons.js';
  import type { LayerTreeNode } from '../shared/layer-tree.js';

  interface Props {
    node: LayerTreeNode;
    depth: number;
    isExpanded: (node: LayerTreeNode) => boolean;
    ontoggle: (node: LayerTreeNode) => void;
  }

  let { node, depth, isExpanded, ontoggle }: Props = $props();
  const editor = getEditorContext();
  const contextMenuEnabled = editor.hasPlugin('exemplara.action-surfaces');
  const expanded = $derived(isExpanded(node));
  const hasChildren = $derived(node.children.length > 0);
  const selected = $derived(
    (node.kind === 'component' && editor.selectedId === node.nodeId)
      || (node.kind === 'page' && editor.selectedId === null && editor.activePageIndex === node.pageIndex),
  );
  const ComponentIcon = $derived(node.componentType ? editor.componentIcon(node.componentType) : null);
  const inlineActions = $derived(node.nodeId
    ? editor.extensions.menuItems('layer.inline', editor, { nodeId: node.nodeId })
    : []);

  function activate(): void {
    if (node.pageIndex !== undefined) editor.activePageIndex = node.pageIndex;
    if (node.kind === 'component' && node.nodeId) {
      editor.select(node.nodeId);
      requestAnimationFrame(() => {
        editor.canvasSurface
          ?.querySelector<HTMLElement>(`[data-node-id="${CSS.escape(node.nodeId!)}"]`)
          ?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      });
    } else if (node.kind === 'page') {
      editor.select(null);
    }
  }

  function rowClick(): void {
    if (node.kind !== 'component' && hasChildren) ontoggle(node);
    activate();
  }

  function runAction(event: MouseEvent, commandId: string): void {
    event.stopPropagation();
    if (!node.nodeId) return;
    void editor.runCommand(commandId, { nodeId: node.nodeId });
  }

  function openMenu(event: MouseEvent): void {
    if (!contextMenuEnabled) return;
    event.preventDefault();
    event.stopPropagation();
    if (!node.nodeId) return;
    editor.openContextMenu(event.clientX, event.clientY, node.nodeId);
  }

  function openMenuFromButton(event: MouseEvent): void {
    const rect = event.currentTarget instanceof HTMLElement
      ? event.currentTarget.getBoundingClientRect()
      : { right: event.clientX, bottom: event.clientY };
    if (!node.nodeId) return;
    event.stopPropagation();
    editor.openContextMenu(rect.right, rect.bottom + 2, node.nodeId);
  }
</script>

<div class="exs-layer-tree-node">
  <div
    role="treeitem"
    tabindex="0"
    aria-level={depth + 1}
    aria-expanded={hasChildren ? expanded : undefined}
    aria-selected={selected}
    data-layer-node-id={node.nodeId}
    class="exs-layer"
    class:exs-layer--selected={selected}
    class:exs-layer--structure={node.kind !== 'component'}
    class:exs-layer--muted={node.hidden}
    style:padding-left={`${6 + depth * 13}px`}
    onclick={rowClick}
    onkeydown={(event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        rowClick();
      } else if (event.key === 'ArrowRight' && hasChildren && !expanded) ontoggle(node);
      else if (event.key === 'ArrowLeft' && hasChildren && expanded) ontoggle(node);
    }}
    onmouseenter={() => { if (node.nodeId) editor.hoveredId = node.nodeId; }}
    onmouseleave={() => { if (editor.hoveredId === node.nodeId) editor.hoveredId = null; }}
    oncontextmenu={openMenu}
  >
    {#if hasChildren}
      <button
        type="button"
        class="exs-layer__disclosure"
        aria-label={expanded ? `Collapse ${node.label}` : `Expand ${node.label}`}
        onclick={(event) => { event.stopPropagation(); ontoggle(node); }}
      >
        {#if expanded}<IconChevronDown size={12} />{:else}<IconChevronRight size={12} />{/if}
      </button>
    {:else}
      <span class="exs-layer__disclosure"></span>
    {/if}

    <span class="exs-layer__icon" data-kind={node.kind}>
      {#if ComponentIcon}
        <ComponentIcon size={13} />
      {:else if node.kind === 'document'}
        <IconLayers size={13} />
      {:else if node.kind === 'page'}
        <IconDocument size={13} />
      {:else if node.kind === 'region'}
        <IconPanel size={13} />
      {:else if node.kind === 'slot'}
        <IconColumns size={13} />
      {/if}
    </span>
    <span class="exs-layer__label" title={node.label}>{node.label}</span>

    {#if node.autoGenerated}<span class="exs-layer__meta">Auto</span>{/if}
    {#if node.continuation}<span class="exs-layer__meta">cont.</span>{/if}
    {#if node.bindingCount}
      <span class="exs-layer__binding" title={`${node.bindingCount} data binding${node.bindingCount === 1 ? '' : 's'}`}>
        <IconDatabase size={10} /> {node.bindingCount}
      </span>
    {/if}
    {#if hasChildren}<span class="exs-layer__count">{node.children.length}</span>{/if}
    {#if node.hidden}<span class="exs-layer__flag" title="Hidden"><IconEyeOff size={11} /></span>{/if}
    {#if node.locked}<span class="exs-layer__flag" title="Locked"><IconLock size={11} /></span>{/if}
    {#if node.kind === 'component'}
      <span class="exs-layer__actions" aria-label={`${node.label} actions`}>
        {#each inlineActions as action (action.id)}
          {@const ActionIcon = action.command.icon ?? IconMore}
          <button
            type="button"
            class="exs-layer__action"
            title={action.command.label}
            aria-label={`${action.command.label} ${node.label}`}
            onclick={(event) => runAction(event, action.command.id)}
          ><ActionIcon size={11} /></button>
        {/each}
        {#if contextMenuEnabled}
          <button type="button" class="exs-layer__action" title="More actions" aria-label={`More actions for ${node.label}`} onclick={openMenuFromButton}><IconMore size={12} /></button>
        {/if}
      </span>
    {/if}
  </div>

  {#if hasChildren && expanded}
    <div role="group" class="exs-layer__children">
      {#each node.children as child (child.id)}
        <LayerItem node={child} depth={depth + 1} {isExpanded} {ontoggle} />
      {/each}
    </div>
  {/if}
</div>
